sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    var ci = g_form.getDisplayBox('cmdb_ci').value;
    alert(ci);
    if (ci.indexOf('*Android') < 1 || ci.indexOf('*blackberry') < 1 || ci.indexOf('*iphone') < 1) {
        g_form.setValue('item_type', 'cmdb_ci_mobile_device');
        g_form.setReadOnly('item_type', true);
    } else if (ci.indexOf('*macbook') < 1) {
        g_form.setValue('item_type', 'cmdb_ci_computer');
        g_form.setReadOnly('item_type', true);
    } else {
        g_form.setReadOnly('item_type', false);
    }

}
